-- Load sales.FactNewBusiness (fact).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/sales/FactNewBusiness.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [sales].[LoadFactNewBusiness]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([FactNewBusiness_SK]), 0)
                              FROM [sales].[FactNewBusiness] WHERE [FactNewBusiness_SK] > 0);

    MERGE [sales].[FactNewBusiness] AS target
    USING (
        SELECT
            CAST(s.[Policy_BK] AS varchar(20)) AS [Policy_BK],
            CAST(s.[DimAgent_SK] AS bigint) AS [DimAgent_SK],
            CAST(s.[ProductCode] AS varchar(20)) AS [ProductCode],
            CAST(s.[AnnualPremiumAmount] AS decimal(18,2)) AS [AnnualPremiumAmount],
            CAST(s.[IssueDate] AS date) AS [IssueDate],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[Policy_BK]) AS [NewKey]
        FROM [stage].[FactNewBusinessSource] AS s
        WHERE s.[IssueDate] >= DATEADD(day, -7, @LoadDate)
    ) AS source
    ON target.[Policy_BK] = source.[Policy_BK]
    WHEN MATCHED AND (
        (target.[DimAgent_SK] <> source.[DimAgent_SK] OR (target.[DimAgent_SK] IS NULL AND source.[DimAgent_SK] IS NOT NULL) OR (target.[DimAgent_SK] IS NOT NULL AND source.[DimAgent_SK] IS NULL))
        OR (target.[ProductCode] <> source.[ProductCode] OR (target.[ProductCode] IS NULL AND source.[ProductCode] IS NOT NULL) OR (target.[ProductCode] IS NOT NULL AND source.[ProductCode] IS NULL))
        OR (target.[AnnualPremiumAmount] <> source.[AnnualPremiumAmount] OR (target.[AnnualPremiumAmount] IS NULL AND source.[AnnualPremiumAmount] IS NOT NULL) OR (target.[AnnualPremiumAmount] IS NOT NULL AND source.[AnnualPremiumAmount] IS NULL))
        OR (target.[IssueDate] <> source.[IssueDate] OR (target.[IssueDate] IS NULL AND source.[IssueDate] IS NOT NULL) OR (target.[IssueDate] IS NOT NULL AND source.[IssueDate] IS NULL))
    ) THEN UPDATE SET
        [DimAgent_SK] = source.[DimAgent_SK],
        [ProductCode] = source.[ProductCode],
        [AnnualPremiumAmount] = source.[AnnualPremiumAmount],
        [IssueDate] = source.[IssueDate],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [FactNewBusiness_SK],
        [Policy_BK],
        [DimAgent_SK],
        [ProductCode],
        [AnnualPremiumAmount],
        [IssueDate],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[Policy_BK],
        source.[DimAgent_SK],
        source.[ProductCode],
        source.[AnnualPremiumAmount],
        source.[IssueDate],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
